    buf[0] = 0x30;
    buf[1] = *(short *)(data + 0x12) / scale_ticks(0xE10) + 0x30;
    buf[2] = 0x3A;
    buf[3] = *(short *)(data + 0x12) % scale_ticks(0xE10) / scale_ticks(0x258) + 0x30;
